// * arbitrary robot bytes are capped and JSON decoding never panics;
// * accepted top-level shapes are objects or arrays, matching br/am/ntm variants;
// * malformed JSON is a typed refusal, never a fabricated empty object;
// * envelope fields, when present, retain their JSON types instead of jq-style coercion.
use libfuzzer_sys::fuzz_target;
use serde_json::Value;

const MAX_INPUT_BYTES: usize = 64 * 1024;

#[derive(Debug, PartialEq, Eq)]
enum EnvelopeRefusal {
    InvalidJson,
    UnsupportedTopLevel,
}

fn decode(data: &[u8]) -> Result<Value, EnvelopeRefusal> {
    let value = serde_json::from_slice(data).map_err(|_| EnvelopeRefusal::InvalidJson)?;
    if !value.is_object() && !value.is_array() {
        return Err(EnvelopeRefusal::UnsupportedTopLevel);
    }
    Ok(value)
}

fuzz_target!(|data: &[u8]| {
    if data.len() > MAX_INPUT_BYTES {
        return;
    }
    match decode(data) {
        Ok(value) => {
            assert!(value.is_object() || value.is_array());
            if let Some(success) = value.get("success") {
                assert!(success.is_boolean());
            }
        }
        Err(EnvelopeRefusal::InvalidJson) | Err(EnvelopeRefusal::UnsupportedTopLevel) => {}
    }
});
